import{_ as t,o,c as n,a3 as a}from"./chunks/framework.WFmvnizL.js";const g=JSON.parse('{"title":"Configuration guide","description":"Configure Nezha Monitoring V2 with a clear workflow for YAML files, environment variables, Dashboard settings, Agent options, deployment examples, and effective verification.","frontmatter":{"description":"Configure Nezha Monitoring V2 with a clear workflow for YAML files, environment variables, Dashboard settings, Agent options, deployment examples, and effective verification.","outline":"deep"},"headers":[],"relativePath":"en_US/configuration/index.md","filePath":"en_US/configuration/index.md","lastUpdated":1792850916000}'),i={name:"en_US/configuration/index.md"};function r(s,e,d,l,c,h){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="configuration-guide" tabindex="-1">Configuration guide <a class="header-anchor" href="#configuration-guide" aria-label="Permalink to &quot;Configuration guide&quot;">​</a></h1><p>Nezha configuration has two independent parts: Dashboard controls entry points, authentication, and storage; Agent controls its connection, collected metrics, and remote-operation capabilities. Each has its own YAML file. Field names and environment-variable rules are not interchangeable.</p><h2 id="choose-a-starting-point" tabindex="-1">Choose a starting point <a class="header-anchor" href="#choose-a-starting-point" aria-label="Permalink to &quot;Choose a starting point&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Goal</th><th>Read</th></tr></thead><tbody><tr><td>Locate the active file and understand loading and persistence</td><td><a href="/en_US/configuration/environment.html">Loading and environment variables</a></td></tr><tr><td>Look up every Dashboard option and default</td><td><a href="/en_US/configuration/dashboard.html">Dashboard configuration</a></td></tr><tr><td>Look up every Agent option and default</td><td><a href="/en_US/configuration/agent.html">Agent configuration</a></td></tr><tr><td>Configure a reverse proxy, built-in HTTPS, lightweight collection, or storage</td><td><a href="/en_US/configuration/examples.html">Configuration recipes and verification</a></td></tr><tr><td>Configure notifications, alerts, tasks, and groups</td><td><a href="/en_US/guide/settings.html">User guide: settings</a> and the adjacent feature pages</td></tr><tr><td>Develop or deploy your own user theme</td><td><a href="/en_US/developer/theme-development.html">Theme development</a></td></tr></tbody></table><h2 id="recommended-workflow" tabindex="-1">Recommended workflow <a class="header-anchor" href="#recommended-workflow" aria-label="Permalink to &quot;Recommended workflow&quot;">​</a></h2><ol><li><strong>Identify how the process runs.</strong> Check container mounts, process arguments, or service definitions. Dashboard defaults to <code>data/config.yaml</code>; Agent defaults to <code>config.yml</code> beside its executable. Installers may specify another location.</li><li><strong>Back up the current state.</strong> Preserve configuration and service definitions. Follow <a href="/en_US/guide/q5.html">backup and recovery</a> for database and TSDB changes. Do not place credentials in shared-readable backups.</li><li><strong>Change one configuration source.</strong> Prefer the admin UI for supported settings. Avoid defining the same field in YAML and the environment. Preserve a local recovery path before changing listeners, TLS, or credentials.</li><li><strong>Apply and read back.</strong> Admin settings generally apply immediately; local file edits require restarting the relevant process. Remote Agent configuration is delayed: successful submission does not prove reconnection.</li><li><strong>Verify the real path.</strong> Confirm the UI loads, Agents keep reporting, history can be queried, intended features work, and disabled capabilities are actually rejected.</li></ol><h2 id="common-distinctions" tabindex="-1">Common distinctions <a class="header-anchor" href="#common-distinctions" aria-label="Permalink to &quot;Common distinctions&quot;">​</a></h2><ul><li>Dashboard <code>tls</code> affects installation commands only. Actual server HTTPS comes from <code>https</code> or a reverse proxy. Agent <code>tls</code> controls the real connection.</li><li><code>install_host</code> is the Agent entry point, <code>dashboard_host</code> is the public Dashboard/OAuth2 callback host, and <code>listen_host</code> is the local bind address.</li><li>A user connection secret registers Agents; it is neither a REST/MCP PAT nor a browser JWT.</li><li><code>online_stats_days</code> controls online-session history; <code>tsdb.retention_days</code> controls time-series retention. Neither replaces the other.</li><li>Theme <code>window.*</code> globals are not Dashboard YAML fields. Put them in <code>custom_code</code>; the selected theme interprets them.</li></ul><h2 id="boundaries-outside-configuration" tabindex="-1">Boundaries outside configuration <a class="header-anchor" href="#boundaries-outside-configuration" aria-label="Permalink to &quot;Boundaries outside configuration&quot;">​</a></h2><p>Agent operations also depend on operating-system permissions. Dashboard user permissions, PAT scopes, and server allowlists still apply. Disabling mandatory login does not publish every server or remove management API authentication. See <a href="/en_US/guide/security.html">security and privacy</a>.</p>',10)])])}const f=t(i,[["render",r]]);export{g as __pageData,f as default};
